/**
 * Collapse a host mount-point's placeholder min-height once our content mounts
 * AND its height has settled.
 *
 * Host templates reserve space with an inline `min-height` placeholder to avoid
 * layout shift before the widget mounts (e.g. the category guide root). Once the
 * widget's content lands and stops resizing, that reservation is released (to
 * `auto`) so the container tracks its real content.
 *
 * We must wait for the *settled* content height, not the first commit. React
 * commits the outer wrapper before its subtree lays out, and the real widget
 * content often arrives several hundred ms later behind async calls
 * (`/initialize`, `/category/questions`). Snapshotting the first child insertion
 * measures a near-zero/teaser height and collapses the reservation immediately,
 * only for the content to paint a few frames later and push everything back down
 * — a visible collapse→refill jump (measured CLS ~0.13 on a cold category page).
 * Instead we hold the reservation and watch the content with a debounced
 * `ResizeObserver`, releasing only once its height has stopped changing (or a
 * safety timeout fires) — collapsing at most once, to the final height.
 *
 * React can commit *after* this runs — consent/feature-flag gates delay the
 * mount, notably in a cold incognito profile — so we wait for the first child
 * via `MutationObserver` instead of snapshotting once.
 *
 * Returns a `cancel()` that clears every pending timer and disconnects both
 * observers. Callers MUST invoke it from destroy()/unmount and before re-mount:
 * otherwise a scheduled callback can fire after the host (or, in tests, the
 * jsdom environment) is gone (SOI-992).
 */

/** No content resize for this long ⇒ treat the height as final and release. */
const SETTLE_MS = 200;
/** Never leave the placeholder min-height stuck if content never settles. */
const SAFETY_MS = 4000;

export function adjustContainerHeight(container: HTMLElement, delayMs = 100): () => void {
  let released = false;
  let startTimer: ReturnType<typeof setTimeout> | null = null;
  let settleTimer: ReturnType<typeof setTimeout> | null = null;
  let safetyTimer: ReturnType<typeof setTimeout> | null = null;
  let observer: MutationObserver | null = null;
  let resizeObserver: ResizeObserver | null = null;

  const disconnectObservers = (): void => {
    observer?.disconnect();
    observer = null;
    resizeObserver?.disconnect();
    resizeObserver = null;
  };

  const release = (): void => {
    if (released) return;
    released = true;
    disconnectObservers();
    if (settleTimer !== null) { clearTimeout(settleTimer); settleTimer = null; }
    if (safetyTimer !== null) { clearTimeout(safetyTimer); safetyTimer = null; }
    // Content now holds the height; drop the floor so the container tracks it.
    container.style.minHeight = 'auto';
  };

  // Debounce: each content resize pushes the release out, so we collapse to the
  // *final* height in one step instead of snapshotting an early commit.
  const scheduleSettle = (): void => {
    if (settleTimer !== null) clearTimeout(settleTimer);
    settleTimer = setTimeout(() => {
      settleTimer = null;
      release();
    }, SETTLE_MS);
  };

  const watch = (content: HTMLElement): void => {
    if (typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(scheduleSettle);
      resizeObserver.observe(content);
    }
    // Kick off the debounce even if the height never changes (already stable, or
    // no ResizeObserver in this environment — e.g. jsdom).
    scheduleSettle();
  };

  const start = (): void => {
    const existing = container.firstElementChild as HTMLElement | null;
    if (existing) {
      watch(existing);
      return;
    }

    observer = new MutationObserver(() => {
      const content = container.firstElementChild as HTMLElement | null;
      if (!content) return;
      observer?.disconnect();
      observer = null;
      watch(content);
    });
    observer.observe(container, { childList: true });
  };

  // Let React commit first, then begin watching. Owning this delay (rather than
  // the caller wrapping the call in its own setTimeout) keeps every handle under
  // one cancel().
  startTimer = setTimeout(() => {
    startTimer = null;
    start();
  }, delayMs);

  // Safety net: release even if content never lands or never stops resizing
  // (e.g. AI-disabled paths handle visibility separately).
  safetyTimer = setTimeout(() => {
    safetyTimer = null;
    release();
  }, SAFETY_MS);

  return function cancel(): void {
    if (startTimer !== null) { clearTimeout(startTimer); startTimer = null; }
    if (settleTimer !== null) { clearTimeout(settleTimer); settleTimer = null; }
    if (safetyTimer !== null) { clearTimeout(safetyTimer); safetyTimer = null; }
    disconnectObservers();
  };
}
